#include <iostream>
#include <string>
#include <regex>

std::string convertMarkdownToHTML(std::string& markdown) {
    // Define regular expressions for common Markdown formatting
    std::regex bold_regex("([*]+)([^*]+)([*]+)");
    std::regex italic_regex("(_)([^_]+)(_)");
    std::regex link_regex("([( ])([^\)]+)([)])(\s*)\(([^)]+)\)");
    std::regex image_regex("!\[(.+)\]\((.+)\)");

    // Define replacements for each Markdown formatting
    std::string bold_replacement("<strong>\\2</strong>");
    std::string italic_replacement("<em>\\2</em>");
    std::string link_replacement("\\1<a href=\\4>\\2</a>");
    std::string image_replacement("<img src=\\2 alt=\\1>");

    // Apply replacements for each Markdown formatting
    markdown = std::regex_replace(markdown, bold_regex, bold_replacement);
    markdown = std::regex_replace(markdown, italic_regex, italic_replacement);
    std::smatch link_match;
    while (std::regex_search(markdown, link_match, link_regex)) {
        markdown = std::regex_replace(markdown, link_regex, link_replacement, std::regex_constants::format_first_only);
    }
    std::smatch image_match;
    while (std::regex_search(markdown, image_match, image_regex)) {
        markdown = std::regex_replace(markdown, image_regex, image_replacement, std::regex_constants::format_first_only);
    }

    return markdown;
}

int main() {
    std::string markdown = "Hello, **bold** and _italic_ text! [Link](https://example.com) and ! [Image](https://example.com/image.png)";
    std::string html = convertMarkdownToHTML(markdown);
    std::cout << html << std::endl; // Output: <p>Hello, <strong>bold</strong> and <em>italic</em> text!</p><br><a href="https://example.com">Link</a> and <img src="https://example.com/image.png" alt="Image"></p>
    return 0;
}
```

En este ejemplo, la función `convertMarkdownToHTML` toma una referencia a un `std::string` llamado `markdown`, que contiene texto con formato Markdown. La función usa expresiones regulares para identificar los formatos de texto fuerte, itálico, enlaces y imágenes en el texto Markdown, y luego realiza las correspondientes sustituciones para convertir el texto a formato HTML. 

